        return kSum(nums, target, 0, 4);
    }
    private List<List<Integer>> kSum(int[] nums, long target, int start, int k) {
        List<List<Integer>> res = new ArrayList<>();
        if (start == nums.length) return res;
        if (k == 2) {
            int l = start, r = nums.length - 1;
            while (l < r) {
                long sum = (long) nums[l] + nums[r];
                if (sum == target) {
                    res.add(new ArrayList<>(Arrays.asList(nums[l], nums[r])));
                    while (l < r && nums[l] == nums[l + 1]) l++;
                    while (l < r && nums[r] == nums[r - 1]) r--;
                    l++; r--;
                } else if (sum < target) l++; else r--;
            }
            return res;
        }
        for (int i = start; i < nums.length - k + 1; i++) {
            if (i > start && nums[i] == nums[i - 1]) continue;
            for (List<Integer> sub : kSum(nums, target - nums[i], i + 1, k - 1)) {
                List<Integer> list = new ArrayList<>();
                list.add(nums[i]); list.addAll(sub);
                res.add(list);
            }
        }
        return res;
    }
}

