class Solution:
    def mergeTwoLists(self, list1: Optional[ListNode], list2: Optional[ListNode]) -> Optional[ListNode]:
        dummy = ListNode(0)
        curr = dummy
        def pick(n1, n2):
            return (n1, n1.next, n2) if n1.val <= n2.val else (n2, n1, n2.next)
        while list1 and list2:
            chosen, list1, list2 = pick(list1, list2)
            curr.next = chosen
            curr = curr.next
        curr.next = list1 or list2
        return dummy.next

