class Solution {
    private void helper(String[] parts, int idx, Deque<String> stack) {
        if (idx == parts.length) return;
        String s = parts[idx];
        if (s.equals("..")) { if (!stack.isEmpty()) stack.pop(); }
        else if (!s.isEmpty() && !s.equals(".")) stack.push(s);
        helper(parts, idx + 1, stack);
    }
    public String simplifyPath(String path) {
        Deque<String> stack = new ArrayDeque<>();
        helper(path.split("/"), 0, stack);
        StringBuilder sb = new StringBuilder();
        while (!stack.isEmpty()) sb.append("/").append(stack.pollLast());
