    public void merge(int[] nums1, int m, int[] nums2, int n) {
        dfs(nums1, m - 1, nums2, n - 1, m + n - 1);
    }
    private void dfs(int[] a, int p1, int[] b, int p2, int p) {
        if (p2 < 0) return;
        if (p1 >= 0 && a[p1] > b[p2]) {
            a[p] = a[p1];
            dfs(a, p1 - 1, b, p2, p - 1);
        } else {
            a[p] = b[p2];
            dfs(a, p1, b, p2 - 1, p - 1);
        }
    }
}

