    public int[] intersection(int[] nums1, int[] nums2) {
        Set<Integer> set = new HashSet<>();
        for (int x : nums1) set.add(x);
        Set<Integer> inter = new HashSet<>();
        dfs(nums2, 0, set, inter);
        int[] ans = new int[inter.size()];
        int i = 0;
        for (int x : inter) ans[i++] = x;
        return ans;
    }
    private void dfs(int[] nums, int i, Set<Integer> set, Set<Integer> inter) {
        if (i == nums.length) return;
        if (set.contains(nums[i])) inter.add(nums[i]);
        dfs(nums, i + 1, set, inter);
    }
}

