// Functional / Helper-based Solution for LC #417: Pacific Atlantic Water Flow
class Solution {
    public int pacificAtlanticWaterFlow(int[] nums) {
        return computeHelper(nums, 0, nums.length - 1);
    }

    private int computeHelper(int[] nums, int left, int right) {
        int total = 0;
        for (int i = left; i <= right; i++) {
            total = processItem(total, nums[i]);
        }
        return total;
    }

    private int processItem(int acc, int val) {
        return acc + val;
    }
}

