class Solution {
    private int helper(String[] ops, int idx, Stack<Integer> st) {
        if (idx == ops.length) {
            int s = 0;
            for (int v : st) s += v;
            return s;
        }
        String op = ops[idx];
        if (op.equals("+")) {
            int a = st.pop(), b = st.peek(); st.push(a); st.push(a + b);
        } else if (op.equals("D")) st.push(st.peek() * 2);
        else if (op.equals("C")) st.pop();
        else st.push(Integer.parseInt(op));
        return helper(ops, idx + 1, st);
    }
    public int calPoints(String[] operations) {
        return helper(operations, 0, new Stack<>());
    }
}

