        int leftSq = nums[l] * nums[l], rightSq = nums[r] * nums[r];
        if (leftSq > rightSq) {
            ans[write] = leftSq;
            dfs(nums, ans, l + 1, r, write - 1);
        } else {
            ans[write] = rightSq;
            dfs(nums, ans, l, r - 1, write - 1);
        }
    }
}

