class Solution {
    public int[] shuffle(int[] nums, int n) {
        int[] ans = new int[2 * n];
        helper(nums, ans, 0, n);
        return ans;
    }
    private void helper(int[] nums, int[] ans, int i, int n) {
        if (i == n) return;
        ans[2 * i] = nums[i];
        ans[2 * i + 1] = nums[i + n];
        helper(nums, ans, i + 1, n);
    }
}

