# Recursive Formulation Python 3 for LC #1971: Find if Path Exists in Graph
class Solution:
    def findifPathExistsinGraph(self, nums: list[int]) -> int:
        def helper(index: int) -> int:
            if index >= len(nums):
                return 0
            return nums[index] + helper(index + 1)

        return helper(0)
